window.GW_GHOST_PRE["ta"] = {"welcomeT":"GHOSTWALK க்கு வரவேற்கிறோம்","welcomeV":"இந்தச் சேவையைப் பயன்படுத்தும் போது குரல் வழிகாட்டுதலைப் பெற விரும்புகிறீர்களா?","hear":"இந்தச் செய்தியைக் கேளுங்கள்","whichLang":"உங்களுக்கு விருப்பமான மொழியைத் தேர்ந்தெடுக்கவும்.","moreLangs":"மேலும் மொழிகள்…","voiceQ":"குரல் வழிகாட்டுதலையும் விரும்புகிறீர்களா?","voiceOn":"குரல் வழிகாட்டுதலை இயக்கு","voiceOff":"உரையுடன் மட்டும் தொடரவும்","allSet":"எல்லாம் தயார். நான் இங்கே மூலையில் இருப்பேன் — உங்களுக்கு உதவி தேவைப்படும்போது என்னைத் தட்டவும்.","close":"மூடு","back":"← பின்","mute":"🔇 ஒலியை முடக்கு","unmute":"🔊 குரல் முடக்கம் — இயக்க தட்டவும்","voiceNA":"இந்தச் சாதனத்தில் இந்த மொழிக்கான குரல் வழிகாட்டுதல் இல்லை. உரை வழிகாட்டுதல் தொடரும்.","pause":"⏸ இடைநிறுத்தம்","resume":"▶ ரெஸ்யூம்","repeat":"🔁 மீண்டும் செய்யவும்","disableV":"குரலை முடக்கு","enableV":"குரலை இயக்கு","changeL":"மொழியை மாற்றவும்","replay":"மீண்டும் வழிகாட்டுதல்","curL":"தற்போதைய மொழி:","menuTitle":"நான் எப்படி உதவ முடியும்?","tGuide":"இந்தப் பக்கத்தின் மூலம் என்னை வழிநடத்துங்கள்","tExplain":"இந்த விருப்பத்தை விளக்குங்கள்","tRepeat":"கடைசி அறிவுறுத்தலை மீண்டும் செய்யவும்","actWhatIsThis":"இது என்ன?","actWhatNext":"நான் இப்போது என்ன செய்ய வேண்டும்?","repeatNone":"இன்னும் மீண்டும் செய்ய முந்தைய அறிவுறுத்தல் இல்லை.","tVoiceOn":"குரல் வழிகாட்டுதல் இயக்கப்பட்டது","tVoiceOff":"குரல் வழிகாட்டுதல் முடக்கப்பட்டுள்ளது","tMin":"குறைக்கவும்","tFull":"முழு உதவியாளரைத் திறக்கவும்","tNext":"அடுத்து","tPrev":"மீண்டும்","tEnd":"இறுதி வழிகாட்டி","tYes":"ஆம், எனக்கு வழிகாட்டு","tNotNow":"இப்போது இல்லை","guideOffer":"இந்த விருப்பங்களுக்கான விரைவான வழிகாட்டியை விரும்புகிறீர்களா?","g_check":"சந்தேகத்திற்குரிய செய்தியை இங்கே ஒட்டவும் அல்லது ஸ்கிரீன்ஷாட் அல்லது ஆவணமாக நீங்கள் பெற்றிருந்தால் பதிவேற்ற விருப்பத்தைப் பயன்படுத்தவும். கடவுச்சொற்கள், OTPகள் அல்லது வங்கிச் சான்றுகளைச் சேர்க்க வேண்டாம். உள்ளடக்கம் தயாரானதும், கீழே உள்ள பகுப்பாய்வு பொத்தானைத் தேர்ந்தெடுக்கவும்.","g_walk":"சந்தேகத்திற்குரிய முதலீட்டு இணைப்பை யாராவது உங்களுக்கு அனுப்பியிருந்தால், அதைத் திறக்காமல் நகலெடுத்து இந்தப் பெட்டியில் ஒட்டவும். நீங்கள் தயாரானதும், \"விசாரணையைத் தொடங்கு\" என்பதைத் தேர்ந்தெடுக்கவும். GHOSTWALK இலக்கைத் தனித்தனியாக ஆய்வு செய்து, அது கவனித்த நடத்தையைத் திருப்பித் தர முயற்சிக்கும்.","g_qr":"முழுமையான QR குறியீட்டைக் கொண்ட புகைப்படம் அல்லது ஸ்கிரீன்ஷாட்டைத் தேர்ந்தெடுக்கவும். கட்டண விண்ணப்பத்தைப் பயன்படுத்தி நீங்கள் அதை ஸ்கேன் செய்ய வேண்டியதில்லை. படத்தைத் தேர்ந்தெடுத்த பிறகு, முன்னோட்டத்தைச் சரிபார்த்து, \"இந்தப் படத்தைப் பயன்படுத்து\" என்பதைத் தேர்ந்தெடுக்கவும்.","g_trusted":"முதலில் சுருக்கத்தை மதிப்பாய்வு செய்யவும். இது துல்லியமாக நிலைமையை விவரிக்கிறது என்றால், நீங்கள் ஈடுபட விரும்பும் நம்பகமான நபரைத் தேர்ந்தெடுக்கவும். GHOSTWALK அவர்களுக்கான எச்சரிக்கைத் தகவலைத் தயாரிக்கும். அனுப்பும் முன் சரிபார்க்கவும்.","g_paid":"கூடுதல் பணம் அனுப்ப வேண்டாம். என்ன, எப்போது செலுத்தப்பட்டது என்பதை பதிவு செய்வதன் மூலம் தொடங்கவும். பின்னர் ஸ்கிரீன் ஷாட்கள், கட்டணக் குறிப்புகள் மற்றும் செய்திகளைப் பாதுகாக்கவும். GHOSTWALK தகவலை ஒழுங்கமைத்து, அடுத்த ஆதரிக்கப்படும் மீட்புப் படிகளைக் காண்பிக்கும்.","g_check_go":"மேலே உள்ள செய்தியைத் தட்டச்சு செய்யவும் அல்லது ஒட்டவும், பின்னர் பகுப்பாய்வைத் தொடங்க இந்த பொத்தானை அழுத்தவும். பேய் இந்த சாதனத்தில் உள்ள அனைத்தையும் படிக்கிறது - எதுவும் திறக்கப்படவில்லை அல்லது பணம் செலுத்தப்படவில்லை.","g_walk_go":"இணைப்பை கீழே பேய் அனுப்ப இந்த பொத்தானை அழுத்தவும். இது பயண சேவையகத்தின் பக்கமாக போலி விவரங்களுடன் நடந்து செல்கிறது மற்றும் பாதுகாப்பாக நிறுத்தப்படும் - அதை நீங்களே திறக்க மாட்டீர்கள்.","g_qr_go":"UPI விவரங்களை ஒட்டிய பிறகு இந்த பொத்தானை அழுத்தவும். பேய் பணம் எங்கு செல்லும் என்பதை டிகோட் செய்து, பணம் பெறுபவருக்கு, தொகை மற்றும் எச்சரிக்கைகளைக் காட்டுகிறது.","g_trusted_go":"விழிப்பூட்டலைத் தயாரிக்க இந்தப் பொத்தானை அழுத்தவும். உங்கள் நம்பகமான நபருடன் பகிர்வதற்கு முன் முன்னோட்டத்தை கவனமாகப் படியுங்கள்.","g_paid_go":"உங்கள் சம்பவ பேக்கை உருவாக்க இந்த பொத்தானை அழுத்தவும். இது உங்கள் காலவரிசை மற்றும் 1930 ஹெல்ப்லைனுக்கான ஆதாரங்களை ஒழுங்கமைக்கிறது - மீட்புக்கு உத்தரவாதம் இல்லை.","m_start":"சேருமிடம் இப்போது தனிமைப்படுத்தப்பட்ட சூழலில் ஆய்வு செய்யப்படுகிறது.","m_done":"விசாரணை முடிந்தது. நான் ஒரு நேரத்தில் கண்டுபிடிப்புகளை விளக்க முடியும்.","langChanged":"மொழி மாறியது. இந்த மொழியில் நான் உங்களுக்கு தொடர்ந்து வழிகாட்டுவேன்.","voiceWelcome":"கோஸ்ட்வாக்கிற்கு வரவேற்கிறோம். உங்களுக்கு வழிகாட்ட நான் இங்கே இருக்கிறேன். நான் ஒவ்வொரு விருப்பத்தையும் விளக்கி, அடுத்து என்ன செய்ய வேண்டும் என்பதைக் காட்ட முடியும்.","textWelcome":"GHOSTWALK க்கு வரவேற்கிறோம். உங்களுக்கு உதவி தேவைப்பட்டால் நான் இங்கே இருக்கிறேன். சிறிய கோஸ்ட் அல்லது ஏதேனும் ஒன்றைத் தட்டவா? விளக்கத்திற்கான ஐகான்.","hintHome":"உதவி தேவையா? தட்டவா? ஏதேனும் ஒரு விருப்பத்தைத் தவிர, அல்லது வழிகாட்டப்பட்ட சுற்றுப்பயணத்திற்கு கோஸ்ட்டைத் திறக்கவும்.","tExplainChoice":"நான் என்ன விளக்க வேண்டும் என்று விரும்புகிறீர்கள்?","explainName_checkMessage":"ஒரு செய்தியைச் சரிபார்க்கவும்","explainName_walkLink":"ஒரு இணைப்பை நடக்கவும்","explainName_qr":"QR / UPI ஐ டிகோட் செய்யவும்","explainName_trustedContact":"நான் நம்பும் ஒருவரை எச்சரிக்கவும்","explainName_alreadyPaid":"நான் ஏற்கனவே பணம் செலுத்தினேன்","vLead":"இங்கே ஏன், எளிய வார்த்தைகளில்.","vReason":"காரணம் {n}:","vExample":"உதாரணமாக:","vRephrase":"வேறு வார்த்தைகளில் கூறுவதானால்,","vDoubt":"சந்தேகம் இருந்தால், இன்னும் செலுத்த வேண்டாம். முதலில் நீங்கள் நம்பும் ஒருவரிடம் பேசுங்கள்.","emptyRead":"இன்னும் படிக்க எதுவும் இல்லை.","translating":"பக்கத்தை மொழிபெயர்க்கிறது — சிறிது நேரம்…","netStruggle":"இந்த நெட்வொர்க்கில் மொழிபெயர்ப்பு சிரமமாக உள்ளது — இப்போதைக்கு ஆங்கிலத்தைக் காட்டுகிறது.","qrUpload":"QR படத்தைப் பதிவேற்றவும்","qrUploadSub":"QR குறியீட்டைக் கொண்ட புகைப்படம் அல்லது ஸ்கிரீன்ஷாட்டைப் பதிவேற்றவும். GHOSTWALK பணம் செலுத்தாமல் அதை டிகோட் செய்யும்.","qrDrop":"… அல்லது ஒரு படத்தை இங்கே இழுத்து விடவும்","qrTakePhoto":"புகைப்படம் எடு","qrUse":"இந்த படத்தை பயன்படுத்தவும்","qrChange":"இன்னொன்றைத் தேர்ந்தெடுங்கள்","qrRemove":"அகற்று","qrNoCode":"இந்தப் படத்திலிருந்து QR குறியீட்டைப் படிக்க முடியவில்லை. முழு QR குறியீட்டையும் காணக்கூடிய தெளிவான படத்தை முயற்சிக்கவும்.","qrTooBig":"அந்த படம் மிகப் பெரியது. 8 எம்பிக்குக் குறைவான படத்தைத் தேர்ந்தெடுக்கவும்.","qrBadFile":"அந்த கோப்பை படமாக படிக்க முடியவில்லை. PNG, JPG அல்லது WebP ஸ்கிரீன்ஷாட்டைத் தேர்ந்தெடுக்கவும்.","qrType":"வகை","qrUpi":"UPI கட்டணக் கோரிக்கை","qrUrl":"இணைய இணைப்பு","qrText":"உரை","qrPayee":"பணம் பெறுபவர் / UPI ஐடி","qrName":"பெயர்","qrAmount":"தொகை","qrNote":"குறிப்பு / குறிப்பு","qrDecodeUpi":"கட்டண நோக்கத்தை டிகோட் செய்யவும்","qrInvestigate":"இந்த இணைப்பைப் பாதுகாப்பாக ஆராயுங்கள்","qrFoundTitle":"QR கண்டறியப்பட்டது","qrGuideSteps":"மாதிரி QR படம் ஏற்றப்பட்டது. படத்தின் முன்னோட்டத்தை மதிப்பாய்வு செய்யவும். இந்தப் படத்தைப் பயன்படுத்து என்பதைத் தேர்ந்தெடுக்கவும். GHOSTWALK இப்போது அதன் உள்ளடக்கங்களை டிகோட் செய்யும்.","g_qr_img":"முதலீடு அல்லது பணம் செலுத்துவதற்காக யாராவது உங்களுக்கு QR குறியீட்டை அனுப்பியிருந்தால், படத்தை இங்கே பதிவேற்றவும். அதில் என்ன இருக்கிறது என்பதைப் பார்க்க, உங்கள் கட்டண விண்ணப்பத்தைப் பயன்படுத்தி அதை ஸ்கேன் செய்ய வேண்டியதில்லை. டிகோடிங் செய்த பிறகு, வேறு எதையும் செய்வதற்கு முன் இலக்கை மதிப்பாய்வு செய்யவும்.","g_qr_found":"QR என்ன கொண்டுள்ளது என்பது இங்கே. எதுவும் செலுத்தப்படவில்லை, எதுவும் திறக்கப்படவில்லை.","sampleNote":"மாதிரி - ஆர்ப்பாட்டத்திற்கு மட்டுமே.","sampleJourneyNote":"கட்டுப்படுத்தப்பட்ட ஆர்ப்பாட்டப் பயணம் - பாதுகாப்பான சோதனை இலக்கு, நேரடி அச்சுறுத்தல் அல்ல.","sampleQrNote":"மாதிரி QR — ஆர்ப்பாட்டம் மட்டுமே. கட்டணம் எதுவும் தொடங்கப்படவில்லை.","sampleCaseNote":"மாதிரி மீட்பு வழக்கு — கற்பனையான டெமோ தரவு. மீட்புக்கு உத்தரவாதம் இல்லை.","sampleAlertText":"GHOSTWALK மேலும் சரிபார்ப்பு தேவை என அடையாளம் காணப்பட்ட முதலீட்டு கோரிக்கையை நான் பெற்றேன். நான் தொடர்வதற்கு முன், இதை என்னுடன் மதிப்பாய்வு செய்ய முடியுமா?","sampleContact":"மாதிரி தொடர்பு","packNeed":"முதலில் நடந்தவற்றில் ஒரு படியாவது சேர்க்கவும்.","carriedOver":"👻 உங்கள் பகுப்பாய்விலிருந்து எடுக்கப்பட்டது — மதிப்பாய்வு செய்து வரைவை அழுத்தவும்.","explain":"விளக்கவும்","readAloud":"சத்தமாக வாசிக்கவும்","notNow":"இப்போது இல்லை","resultsReady":"உங்கள் முடிவு கீழே தயாராக உள்ளது. என்னைத் தட்டவும், நான் அதை எளிமையாக விளக்குகிறேன்.","uncertain":"இதை எங்களால் நம்பகத்தன்மையுடன் சரிபார்க்க முடியவில்லை. அது பாதுகாப்பானது என்று அர்த்தமல்ல. நீங்கள் சுயாதீனமாக சரிபார்க்கும் வரை தொடர வேண்டாம்.","checking":"காசோலை கீழே இயங்குகிறது. இது சேருமிடத்தை தனிமையில் படிக்கிறது, எனவே நீங்களே எதையும் தொட வேண்டியதில்லை.","understood":"புரிந்தது. உங்களுக்குத் தேவைப்பட்டால் நான் இங்கே இருக்கிறேன்.","noResult":"முதலில் ஒரு காசோலையை இயக்கவும் - அதன் பிறகு என்ன கண்டுபிடித்தது என்பதை என்னால் விளக்க முடியும்.","m_index_t":"GHOSTWALK என்ன செய்கிறது","m_index":["நீங்கள் பெற்றதைத் தேர்ந்தெடுக்கவும்: செய்தி, இணைப்பு, QR, நம்பகமான நபர் அல்லது ஏற்கனவே பணம் செலுத்திய உதவி.","சந்தேகத்திற்கிடமான இணைப்புகளை நீங்களே திறக்க மாட்டீர்கள் - பேய் அவற்றை சர்வர் பக்கமாக நடத்துகிறது.","நீங்கள் எப்போதாவது நிறுத்தப்படுவீர்கள் அல்லது சரிபார்க்கப்படவில்லை. ஒருபோதும் தவறான \"பாதுகாப்பான\"."],"m_message_t":"ஒரு செய்தியைச் சரிபார்க்கிறது","m_message":["உரை தாவலில் அரட்டையை ஒட்டவும் மற்றும் பகுப்பாய்வு என்பதை அழுத்தவும்.","புகைப்படத் தாவல் ஸ்கிரீன் ஷாட்களைப் படித்து மறைக்கப்பட்ட QR குறியீடுகளைக் கண்டறியும்.","PDF தாவல் பிரசுரங்களைப் படிக்கிறது. தட்டச்சு செய்வதற்குப் பதிலாக குரல் தாவல் உங்களைப் பேச அனுமதிக்கிறது."],"m_ghost_t":"ஒரு இணைப்பை நடைபயிற்சி","m_ghost":["சந்தேகத்திற்கிடமான இணைப்பை பெட்டியில் ஒட்டவும். அதை நீங்களே திறக்க வேண்டாம்.","\"பேய் அனுப்பு\" என்பதை அழுத்தி கீழே உள்ள ரீப்ளே பார்க்கவும்.","பேய் போலியான விவரங்களை மட்டுமே பயன்படுத்துகிறது - ஒருபோதும் உங்களுடையது அல்ல."],"m_qr_t":"QR / UPI ஐப் படித்தல்","m_qr":["QRக்கு பின்னால் மறைந்திருக்கும் UPI சரத்தை ஒட்டவும் - அதை நீங்களே ஸ்கேன் செய்ய வேண்டாம்.","அந்த பணம் உண்மையில் எங்கு செல்லும் என்பதை பேய் படிக்கிறது.","காட்டப்பட்ட பெயரை உண்மையான நிறுவனத்துடன் தனித்தனியாக ஒப்பிடவும்."],"m_trusted_t":"நீங்கள் நம்பும் ஒருவரைக் கேட்பது","m_trusted":["பெயர் மற்றும் தொகையை நிரப்பவும், பின்னர் வரைவை அழுத்தவும்.","வாட்ஸ்அப்பில் குறுஞ்செய்தியை உங்கள் குடும்பத்தினருடன் பகிர்ந்து கொள்ளுங்கள்.","அவர்கள் எதையும் அங்கீகரிக்கவில்லை - அவர்கள் உங்களுடன் நிற்கிறார்கள்."],"m_recovery_t":"நீங்கள் ஏற்கனவே பணம் செலுத்தியிருந்தால்","m_recovery":["என்ன நடந்தது என்பதை படிப்படியாக சேர்க்கவும்.","“Build my incident pack” என்பதை அழுத்தி பதிவிறக்கவும்.","அதை உங்கள் வங்கி மற்றும் ஹெல்ப்லைன் 1930க்கு எடுத்துச் செல்லுங்கள். மேலும் பணம் செலுத்துவதை நிறுத்துங்கள்."],"understand":"எனது முடிவைப் புரிந்து கொள்ளுங்கள்","saidRed":"இது STOP என்று கூறுகிறது. பணம் செலுத்த வேண்டாம் மற்றும் OTP அல்லது வங்கி விவரங்களைப் பகிர வேண்டாம்.","saidYellow":"இது NOT VERIFIED என்று கூறுகிறது. இன்னும் பணம் செலுத்தாதீர்கள்.","ai_title":"கோஸ்ட் AI","ai_assisted":"AI-உதவி விளக்கம்","ai_note":"இந்த கண்டுபிடிப்பை விளக்குவதற்கு தேவையான தகவல்களை மட்டுமே கோஸ்ட் பெறுகிறது. AI செயலாக்கத்திற்கு முன் உணர்திறன் விவரங்கள் அகற்றப்படும்.","ai_why_data":"AIக்கு இது ஏன் தேவை","ai_privacy":"தனியுரிமை","ai_p1":"கண்டுபிடிப்புகளை விளக்குவதற்கும் இந்த இடைமுகத்தின் மூலம் உங்களுக்கு வழிகாட்டுவதற்கும் மட்டுமே AI பயன்படுத்தப்படுகிறது.","ai_p2":"எதையும் செயலாக்கும் முன், முக்கியமான தகவல்கள் குறைக்கப்பட்டு, திருத்தப்படும்.","ai_p3":"GHOSTWALK இல் எங்கும் OTP, PIN, கடவுச்சொல் அல்லது அட்டை பாதுகாப்புக் குறியீட்டை உள்ளிட வேண்டாம்.","ai_p4":"வெளிப்புற AI செயலாக்கம் அது உள்ளமைக்கப்பட்ட இடத்தில் மட்டுமே நடக்கும் மற்றும் நீங்கள் கேட்ட விளக்கத்திற்கு மட்டுமே.","ai_p5":"AI உதவியின்றி ஒவ்வொரு முக்கிய GHOSTWALK அம்சத்தையும் நீங்கள் பயன்படுத்தலாம்.","ai_simple":"எளிமையாக விளக்குங்கள்","ai_why":"இது ஏன் முக்கியம்?","ai_next":"அடுத்து நான் என்ன செய்ய வேண்டும்?","ai_overview":"கண்டுபிடிக்கப்பட்டதை விளக்குங்கள்","ai_working":"மொழிபெயர்க்கிறது…","ai_basic":"உள்ளமைக்கப்பட்ட விளக்கத்தைக் காட்டுகிறது","ai_unavail":"AI உதவி இப்போது கிடைக்கவில்லை, அதற்குப் பதிலாக இதோ உள்ளமைக்கப்பட்ட விளக்கம்.","ai_src_ai":"AI-உதவி","ai_src_basic":"உள்ளமைக்கப்பட்ட","ai_privacy_short":"AI செயலாக்கத்திற்கு முன் முக்கிய விவரங்கள் அகற்றப்பட்டன","ai_consent_q":"AI ஐப் பயன்படுத்தி இந்த உள்ளடக்கத்தை விளக்க, GHOSTWALK கண்டறியப்பட்ட முக்கியமான தகவலை அகற்றிய பிறகு உரையைச் செயலாக்க வேண்டும். தொடரவா?","ai_consent_yes":"தொடரவும்","ai_consent_no":"அதற்கு பதிலாக அடிப்படை பகுப்பாய்வு பயன்படுத்தவும்","ai_offtopic":"நான் GHOSTWALK, மோசடி பாதுகாப்பு மற்றும் முதலீட்டாளர் பாதுகாப்பிற்கு மட்டுமே உதவுகிறேன். முதலீடுகள், பங்குகள் அல்லது வர்த்தகங்களை என்னால் பரிந்துரைக்க முடியாது.","ai_retry":"மீண்டும் முயற்சிக்கவும்","ai_never":"OTP, PIN, கடவுச்சொல் அல்லது அட்டை பாதுகாப்புக் குறியீட்டை யாருடனும் பகிர வேண்டாம்.","ai_missing_key":"இந்த விளக்கம் உங்கள் மொழியில் இன்னும் கிடைக்கவில்லை. GHOSTWALK இன் மற்ற எல்லா பகுதிகளும் இன்னும் செயல்படுகின்றன, மேலும் கீழே உள்ள உள்ளமைக்கப்பட்ட பதில் எப்போதும் காட்டப்படும்.","ai_send_none":"இந்த விளக்கத்திற்காக எந்த AI வழங்குநருக்கும் எதுவும் அனுப்பப்படவில்லை.","gd_red_simple":"GHOSTWALK விசாரிக்கும் போது குறிப்பிட்ட எச்சரிக்கை அறிகுறிகளைக் கண்டது. ஏதோ ஆபத்தானது காணப்பட்டது, மேலும் எச்சரிக்கைகள் இல்லாதது பாதுகாப்புக்கான ஆதாரம் அல்ல.","gd_red_why":"கவனிக்கப்பட்டவை ஆதாரமாக பதிவு செய்யப்படுகின்றன, நிரூபிக்கப்பட்ட நீதிமன்ற வழக்காக அல்ல. நிறுத்துவதை நியாயப்படுத்துவது இன்னும் போதுமானது, ஏனென்றால் பணம் அனுப்புவது அல்லது OTP ஐப் பகிர்வதை செயல்தவிர்க்க முடியாது.","gd_red_next":"பணம் அனுப்ப வேண்டாம் மற்றும் OTP, PIN, கடவுச்சொல் அல்லது அட்டை பாதுகாப்பு குறியீட்டைப் பகிர வேண்டாம். வேறு எதையும் செய்வதற்கு முன், இந்த உரையாடலுக்கு வெளியே நிறுவனத்தை சுயாதீனமாக சரிபார்க்கவும்.","gd_yellow_simple":"இந்த பயணத்தை நம்பும் அளவுக்கு GHOSTWALK ஐ நிறுவ முடியவில்லை. இது பாதுகாப்பானது என்று அர்த்தமல்ல, அது மோசடி என்று அர்த்தமல்ல.","gd_yellow_why":"சரிபார்க்கப்படவில்லை என்றால் காசோலைகள் எதையும் உறுதிப்படுத்தவோ அல்லது மறுக்கவோ முடியாது. சரிபார்ப்பு இல்லாமல் செயல்படும் ஆபத்து முற்றிலும் உங்கள் மீது விழுகிறது.","gd_yellow_next":"இந்த உரையாடலுக்கு வெளியே நிறுவனம் சுயாதீனமாக சரிபார்க்கப்படும் வரை பணம் செலுத்த வேண்டாம் மற்றும் தனிப்பட்ட விவரங்களைப் பகிர வேண்டாம்.","gd_none_simple":"இன்னும் எதுவும் சரிபார்க்கப்படவில்லை, எனவே நான் விளக்குவதற்கு எதுவும் இல்லை.","gd_none_why":"ஒரு விளக்கம் உண்மையில் கவனிக்கப்பட்டதை மட்டுமே விவரிக்க முடியும். சரிபார்ப்பு இல்லாமல், எந்த விளக்கமும் யூகமாக இருக்கும்.","gd_none_next":"முதலில் காசோலையை இயக்கவும், பின்னர் அது என்ன கண்டுபிடிக்கப்பட்டது என்பதை விளக்குமாறு என்னிடம் கேளுங்கள்.","gc_payment_destination_simple":"சரிபார்க்கப்பட்ட நிறுவனத்துடன் GHOSTWALK பொருந்தாத கட்டண முகவரிக்கு பணம் உங்கள் கணக்கை விட்டுச் செல்லும்.","gc_payment_destination_why":"பணம் செலுத்தும் முகவரி என்பது உங்கள் பணத்தைப் பெறும் நபர் அல்லது வணிகமாகும். இது சுயாதீனமாக சரிபார்க்க முடியாததால், உண்மையில் யார் பணம் பெறுவார்கள் என்பதை உறுதிப்படுத்த எந்த வழியும் இல்லை.","gc_payment_destination_next":"இன்னும் செலுத்த வேண்டாம். நீங்கள் ஏற்கனவே நம்பும் இணையதளம் அல்லது ஃபோன் எண்ணைப் பயன்படுத்தி, உங்கள் கட்டணப் பயன்பாட்டில் காட்டப்பட்டுள்ள பணம் பெறுபவரின் பெயரை அதிகாரப்பூர்வ நிறுவனத்தின் பெயருடன் ஒப்பிடவும்.","gc_withdrawal_trap_simple":"நீங்கள் ஏற்கனவே அனுப்பிய பணத்தைப் பெறுவதற்கு முன் மற்றொரு கட்டணம் கோரப்படுகிறது.","gc_withdrawal_trap_why":"முறையான திரும்பப் பெறுதல்கள் இருப்புத்தொகையிலிருந்து கட்டணங்களைக் கழிக்கின்றன. நிதியை வெளியிடுவதற்கு முன் புதிய கட்டணத்திற்கான தனி கோரிக்கை ஒரு நன்கு அறியப்பட்ட பொறியாகும், மேலும் முதல் கட்டணம் பொதுவாக திரும்பப் பெறப்படாது.","gc_withdrawal_trap_next":"மேலும் பணம் செலுத்துவதை நிறுத்துங்கள். நிதியை வெளியிடுவதற்காக கட்டணம், வரி அல்லது வைப்புத்தொகையை அனுப்ப வேண்டாம். ஏற்கனவே அனுப்பப்பட்ட பணத்தை இழந்ததாகக் கருதி உடனடியாக உங்கள் வங்கியைத் தொடர்புகொள்ளவும்.","gc_redirect_identity_simple":"இங்கே வருவதற்கு முன், இணைப்பு மற்ற இணைய முகவரிகள் மூலம் உங்களை நகர்த்தியது, எனவே இறுதிப் பக்கம் இணைப்பு காட்டப்பட்டதாக இல்லை.","gc_redirect_identity_why":"ஒவ்வொரு ஹாப்பும் நீங்கள் கிளிக் செய்த இணைப்பில் தெரியும் எதையும் மாற்றாமல் நீங்கள் காட்டப்படுவதை மாற்றுவதற்கான வாய்ப்பாகும். நீங்கள் திறந்ததாக நினைத்த அமைப்பு வேறுபட்டதாக இருக்கலாம்.","gc_redirect_identity_next":"பயணத்தை நிறுத்துங்கள், இந்தப் பக்கத்தில் எதையும் உள்ளிட வேண்டாம். உங்களுக்கு ஏற்கனவே தெரிந்த முகவரியைத் தட்டச்சு செய்வதன் மூலம் அதிகாரப்பூர்வ இணையதளத்தைத் திறக்கவும், பின்னர் சலுகை உள்ளதா என்பதைச் சரிபார்க்கவும்.","gc_lookalike_address_simple":"எழுதப்பட்ட முகவரி நம்பகமான நிறுவனமாகத் தோற்றமளிக்கும் வகையில் வடிவமைக்கப்பட்டுள்ளது, ஆனால் அந்த அமைப்பு அல்ல.","gc_lookalike_address_why":"எழுத்துகள் பார்வைக்கு ஒரே மாதிரியான எழுத்துக்களால் மாற்றப்படலாம் அல்லது @ குறியீட்டிற்கு முன் உரை மறைக்கப்படலாம், எனவே முகவரியானது வங்கி அல்லது தரகர் போல் வேறு எங்காவது சுட்டிக்காட்டுகிறது.","gc_lookalike_address_next":"தொடர வேண்டாம். உங்கள் வங்கி அட்டையில் உள்ள எண் அல்லது அதன் அதிகாரப்பூர்வ ஆப்ஸ் போன்ற நீங்கள் ஏற்கனவே நம்பும் சேனல் மூலம் நிறுவனத்தைச் சரிபார்க்கவும். ஒரே அரட்டையில் அல்லது ஒரே பக்கத்தில் சரிபார்க்க வேண்டாம்.","gc_transport_security_simple":"இந்தப் பக்கத்திற்கான இணைப்பு பாதுகாப்பாக இல்லை அல்லது தளத்தால் அது யார் என்பதை நிரூபிக்க முடியவில்லை.","gc_transport_security_why":"சரியான சான்றிதழ் இல்லாமல், இணைப்பை இயக்குபவர் நீங்கள் தட்டச்சு செய்வதைப் படித்து மாற்றலாம். வேறொரு தளத்திற்குப் பெயரிடும் சான்றிதழானது, பக்கத்திற்குச் சொந்தமில்லாத இடத்திலிருந்து வழங்கப்படுகிறது.","gc_transport_security_next":"தனிப்பட்ட அல்லது நிதி விவரங்களை உள்ளிட வேண்டாம். பக்கத்தை விட்டு வெளியேறி, சுயாதீனமாக அணுகப்பட்ட நிறுவனத்தின் அதிகாரப்பூர்வ பயன்பாடு அல்லது இணையதளத்தை மட்டும் பயன்படுத்தவும்.","gc_credentials_request_simple":"இந்த பக்கம் தனிப்பட்ட அல்லது நிதி விவரங்களைக் கேட்கிறது, இது எந்த முறையான முதலீட்டுப் பக்கமும் தேவையில்லை.","gc_credentials_request_why":"OTP, கடவுச்சொல், பின் அல்லது அட்டை பாதுகாப்புக் குறியீடு பணம் செலுத்துவதை அங்கீகரிக்கலாம் அல்லது உங்கள் கணக்கிற்கான அணுகலை வழங்கலாம். எந்தவொரு உண்மையான ஆதரவுப் பிரதிநிதியும் ஒருவரைப் பகிருமாறு உங்களிடம் கேட்கக்கூடாது.","gc_credentials_request_next":"எதையும் பகிரவும். நீங்கள் ஏற்கனவே OTP அல்லது கடவுச்சொல்லை உள்ளிட்டிருந்தால், கடவுச்சொல்லை மாற்றி உடனடியாக உங்கள் வங்கியை அழைக்கவும், பின்னர் சைபர் கிரைம் ஹெல்ப்லைன் 1930 இல் புகாரளிக்கவும்.","gc_device_control_simple":"திரைப் பகிர்வு அல்லது உங்கள் கேமரா மற்றும் மைக்ரோஃபோனுக்கான அணுகல் போன்ற உங்கள் சாதனத்தின் மீதான கட்டுப்பாட்டை பக்கம் கேட்கிறது.","gc_device_control_why":"தொலைநிலை அணுகல் மற்றொரு நபரை நீங்கள் செய்யும் அனைத்தையும் பார்க்கவும், உங்கள் வங்கி பயன்பாட்டில் நீங்கள் உள்ளிடும் அனைத்தும் உட்பட உங்கள் சார்பாக தரவை உள்ளிடவும் அனுமதிக்கிறது.","gc_device_control_next":"கோரிக்கையை நிராகரித்து பக்கத்தை மூடவும். நீங்கள் சந்திக்காத ஒருவருக்கு தொலைநிலை அணுகல் மென்பொருளை நிறுவ வேண்டாம். நீங்கள் ஏற்கனவே நிறுவியிருந்தால், உங்கள் இணையத்தை அணைத்துவிட்டு, நீங்கள் நம்பும் ஒருவரிடம் உதவி கேட்கவும்.","gc_app_install_simple":"அதிகாரப்பூர்வ கடைக்கு வெளியே நிறுவப்பட்ட பயன்பாட்டிற்கு உங்களை நகர்த்த பக்கம் முயற்சித்தது.","gc_app_install_why":"இந்த வழியில் நிறுவப்பட்ட ஆப்ஸ் ஸ்டோர் காசோலைகளைத் தவிர்த்து, உங்கள் செய்திகள், அறிவிப்புகள் மற்றும் வங்கி விவரங்களைப் படிக்க முடியும்.","gc_app_install_next":"அதை நிறுவ வேண்டாம். ஏற்கனவே பதிவிறக்கம் செய்யப்பட்ட எதையும் நீக்கி, நீங்கள் வழக்கமாகப் பயன்படுத்தும் ஸ்டோரில் இருந்து அதன் அதிகாரப்பூர்வ பயன்பாட்டின் மூலம் மட்டுமே நிறுவனத்தை அணுகவும்.","gc_new_domain_simple":"இந்த இணையதளம் சில நாட்களுக்கு முன்பு உருவாக்கப்பட்டது.","gc_new_domain_why":"மோசடி நடவடிக்கைகள் பொதுவாக விரைவாக கட்டமைக்கப்பட்டு விரைவாக கைவிடப்படுகின்றன. எந்த வரலாறும் இல்லாத தளம், இப்போது மாற்றப்பட்ட ஒரு நிறுவப்பட்ட நிறுவனத்தை விட புதியதாக இருக்கும்.","gc_new_domain_next":"சலுகை சரிபார்க்கப்படாததாகக் கருதுங்கள். இந்த இணைப்பைப் பயன்படுத்தாமல் நீங்கள் அணுகக்கூடிய அதிகாரப்பூர்வ இணையதளம், பயன்பாடு அல்லது பதிவு நிறுவனத்திடம் உள்ளதா எனச் சரிபார்க்கவும்.","gc_pressure_simple":"பக்கம் அல்லது செய்தி உங்களை இப்போதே செயல்பட வைக்க நேர அழுத்தத்தைப் பயன்படுத்துகிறது.","gc_pressure_why":"அழுத்தம் என்பது உங்களை சிந்திக்க அல்லது நீங்கள் நம்பும் ஒருவரைக் கேட்பதைத் தடுக்க வடிவமைக்கப்பட்டுள்ளது. ஒரு உண்மையான முதலீட்டு வாய்ப்பு நாளையும் உள்ளது, ஆனால் கவுண்டவுன் பொதுவாக இல்லை.","gc_pressure_next":"நிறுத்தி காத்திருங்கள். பக்கத்தை மூடிவிட்டு, எதையும் செய்வதற்கு முன் நிறுவனத்தை சுயாதீனமாக சரிபார்க்கவும்.","gc_deception_simple":"பக்கம் மற்றவர்களின் வெற்றியை ஆதாரமாகப் பயன்படுத்தியது அல்லது விஷயத்தை ரகசியமாக வைத்திருக்கும்படி உங்களிடம் கேட்டது.","gc_deception_why":"லாபத்தின் ஸ்கிரீன் ஷாட்களை உருவாக்குவது எளிதானது, மேலும் இரகசியத்தைக் கேட்பது வேலை செய்யும் ஒரு பாதுகாப்பை நீக்குகிறது: உங்களுக்குத் தெரிந்த ஒருவரிடமிருந்து இரண்டாவது கருத்து.","gc_deception_next":"சான்றுகளை நம்ப வேண்டாம். இந்த உரையாடலில் செயல்படும் முன், நீங்கள் நம்பும் ஒருவரிடம் சலுகையைக் காட்டுங்கள்.","gc_off_channel_simple":"உரையாடல் தனிப்பட்ட அரட்டை பயன்பாட்டிற்கு அல்லது திரைப் பகிர்வுக்கு நகர்த்தப்பட்டது.","gc_off_channel_why":"தனியார் சேனல்கள் நீங்கள் திரும்பப் பெறக்கூடிய எந்தப் பதிவையும் விட்டுவிடவில்லை, மேலும் நீங்கள் பேசும் நபரை இனி எந்த அதிகாரப்பூர்வ சேனலுக்கு எதிராகவும் சரிபார்க்க முடியாது.","gc_off_channel_next":"உரையாடலை மீண்டும் அதிகாரப்பூர்வ சேனலுக்கு நகர்த்தவும் அல்லது நிறுத்தவும். தனிப்பட்ட அரட்டை பயன்பாட்டில் தொடர வேண்டாம்.","gc_escalation_simple":"கேட்கப்படும் தொகை தொடர்ந்து அதிகரித்து வருகிறது, மேலும் உத்தரவாதம் அல்லது வழக்கத்திற்கு மாறாக அதிக வருமானம் உறுதியளிக்கப்பட்டது.","gc_escalation_why":"உண்மையான முதலீடுகள் எப்பொழுதும் ரிஸ்க்கைக் கொண்டிருக்கின்றன மற்றும் லாபத்திற்கு உத்தரவாதம் அளிக்காது. சிறியதாகத் தொடங்கி பின்னர் வளரும் ஒரு முறை, நீங்கள் இழப்பதை அதிகரிக்க வடிவமைக்கப்பட்டுள்ளது.","gc_escalation_next":"அடுத்த கட்டணம் செலுத்த வேண்டாம். உத்தரவாதமான வருவாய் என்பது தெளிவான எச்சரிக்கை அறிகுறியாகும்.","gc_unreachable_simple":"இலக்கை ஒருமுறை கூட ஏற்ற முடியவில்லை, அதனால் அதைப் பற்றி எதுவும் சரிபார்க்க முடியவில்லை.","gc_unreachable_why":"நம்பகத்தன்மையுடன் ஏற்றப்படாத முகவரியை ஆய்வு செய்ய முடியாது. இது ஆதாரம் இல்லாதது, பாதுகாப்புக்கான ஆதாரம் அல்ல.","gc_unreachable_next":"சலுகை சரிபார்க்கப்படாததாகக் கருதி, பணம் செலுத்த வேண்டாம். இது உங்களுக்காக வேலை செய்தது என்பது பாதுகாப்பானது என்று அர்த்தமல்ல.","gc_third_party_content_simple":"இந்தப் பக்கம் ஒரே இணையதளமாக இயங்கவில்லை. இது பல வெளிப்புற சேவைகளிலிருந்து ஒன்றாக இணைக்கப்பட்டுள்ளது.","gc_third_party_content_why":"பல வெளிப்புறச் சேவைகளிலிருந்து ஒரு பக்கம் கட்டமைக்கப்படும்போது, ​​அவற்றில் ஏதேனும் ஒன்று நீங்கள் பார்ப்பதை மாற்றலாம், அவற்றில் எதுவுமே உங்களுக்குப் பொறுப்பாகாது.","gc_third_party_content_next":"இந்தப் பக்கத்தில் எதையும் உள்ளிட வேண்டாம். நிறுவனத்தை அதன் சொந்த இணையதளம் அல்லது ஆப்ஸ் மூலம் அணுகவும்.","gc_unverified_simple":"GHOSTWALK இந்த அவதானிப்பை பதிவு செய்தது, ஆனால் அதற்கான எளிய மொழி விளக்கம் இன்னும் கிடைக்கவில்லை.","gc_unverified_why":"அவதானிப்பு ஆதாரமாக பதிவு செய்யப்பட்டுள்ளது. இது மேலும் சரிபார்க்கப்படவில்லை, எனவே அதிலிருந்து எந்த முடிவும் எடுக்கப்படக்கூடாது.","gc_unverified_next":"இதன் காரணமாக எந்த தனிப்பட்ட விவரங்களையும் செலுத்தவோ அல்லது பகிரவோ வேண்டாம். காசோலையை மீண்டும் இயக்கவும் அல்லது நிறுவனத்தை சுயாதீனமாக சரிபார்க்கவும்."};
